-- Patient photo: the image file lives in UPLOAD_DIR/patients (served only through the
-- authenticated API), the table stores its generated file name.
ALTER TABLE patients
    ADD COLUMN photo            VARCHAR(64),
    ADD COLUMN photo_updated_at TIMESTAMPTZ,
    -- Only names generated by the API (UUID + extension) are accepted: no path can be injected.
    ADD CONSTRAINT patients_photo_filename_valid
        CHECK (photo ~ '^[0-9a-f-]{36}\.(jpg|png|webp)$'),
    -- photo_updated_at versions the photo URL, so it is set (or cleared) together with the photo.
    ADD CONSTRAINT patients_photo_consistent
        CHECK ((photo IS NULL) = (photo_updated_at IS NULL));
